const countryHeading = document.getElementById("countryHeading");
const citizenshipSelect = document.getElementById("citizenship");

function buildCountryOptions(items) {
  citizenshipSelect.replaceChildren();

  const placeholderOption = document.createElement("option");
  placeholderOption.value = "";
  placeholderOption.textContent = "Select a Country";
  citizenshipSelect.appendChild(placeholderOption);

  items.forEach(function (item) {
    const option = document.createElement("option");
    option.value = item.code;
    option.textContent = item.label;
    citizenshipSelect.appendChild(option);
  });
}

citizenshipSelect.addEventListener("change", function () {
  const selectedOption =
    citizenshipSelect.options[citizenshipSelect.selectedIndex];
  const countryName = selectedOption.text;

  countryHeading.textContent = "Country: " + countryName;
});

